"use client"

import * as React from "react"
import { Progress as ProgressPrimitive } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { progressFillRecipe, progressTrackRecipe } from "@/lib/ink/recipes/progress-ink"
import { cn } from "@/lib/utils"

function Progress({
  className,
  value,
  seed,
  ref,
  ...props
}: React.ComponentProps<typeof ProgressPrimitive.Root> & { seed?: string | number }) {
  const disabled = props["aria-disabled"] === true || props["aria-disabled"] === "true"
  const { hostRef, hostProps, node, seed: hostSeed } = useInk({
    recipe: progressTrackRecipe,
    params: { disabled },
    kind: "progress",
    seed,
    still: true,
  })

  return (
    <ProgressPrimitive.Root
      data-slot="progress"
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...hostProps}
      value={value}
      className={cn("relative isolate h-2 w-full overflow-hidden rounded-full", className)}
      {...props}
    >
      {node}
      <ProgressIndicator value={value} seed={hostSeed} disabled={disabled} />
    </ProgressPrimitive.Root>
  )
}

function ProgressIndicator({
  value,
  seed,
  disabled,
  className,
  ref,
  ...props
}: React.ComponentProps<typeof ProgressPrimitive.Indicator> & {
  value?: number | null
  seed: string
  disabled?: boolean
}) {
  const { hostRef, hostProps, node } = useInk({
    recipe: progressFillRecipe,
    params: { disabled: !!disabled },
    kind: "progress-fill",
    seed: `${seed}-fill`,
    still: true,
  })

  return (
    <ProgressPrimitive.Indicator
      data-slot="progress-indicator"
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...hostProps}
      className={cn("h-full w-full flex-1 transition-transform duration-(--sd-dur-pop) ease-out", className)}
      style={{ transform: `translateX(-${100 - (value ?? 0)}%)` }}
      {...props}
    >
      {node}
    </ProgressPrimitive.Indicator>
  )
}

export { Progress }

import { wash } from '@/lib/ink/fills'
import { pillPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export interface ProgressTrackParams {
  disabled?: boolean
}

export const progressTrackRecipe = defineRecipe<ProgressTrackParams>({
  id: 'progress-track',
  kind: 'progress',
  layers: ['rest'],
  pad: 6,
  draw(ink, { w, h }) {
    const r = h / 2
    const body = pillPoly(0.4, 0.4, w - 0.8, h - 0.8)
    ink.layer('rest', () => {
      softFill(ink, body, [
        { color: 'sand-shade', alpha: 0.5, wobble: 0.45 },
        { color: 'sand-slip', alpha: 0.22, inset: 0.5 },
      ])
      box(ink, 0.45, 0.45, w - 0.9, h - 0.9, {
        pen: 'pencil.fine',
        corner: r,
        loose: 0.65,
        opts: { alpha: 0.42, simple: true, color: 'line-soft' },
      })
    })
  },
})

export interface ProgressFillParams {
  disabled?: boolean
}

export const progressFillRecipe = defineRecipe<ProgressFillParams>({
  id: 'progress-fill',
  kind: 'progress-fill',
  layers: ['rest'],
  pad: 6,
  draw(ink, { w, h }, { disabled }) {
    const r = Math.max(1, h / 2 - 0.2)
    const body = pillPoly(0.35, 0.35, Math.max(1, w - 0.7), h - 0.7)
    ink.layer('rest', () => {
      if (disabled) {
        wash(ink, body, 'sand-shade', { alpha: 0.32, material: 'wash', wobble: 0.4 })
        return
      }
      softFill(ink, body, [
        { color: 'rose-wash', alpha: 0.55, wobble: 0.58 },
        { color: 'horizon', alpha: 0.32, inset: 0.55 },
      ])
      if (w > 6) {
        box(ink, 0.5, 0.5, w - 1, h - 1, {
          pen: 'horizonPencil.fine',
          corner: r,
          loose: 0.5,
          opts: { alpha: 0.48, simple: true },
        })
      }
    })
  },
})

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
